const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helper to getInfo as Promise
  function getInfoAsync(obj) {
    return new Promise((resolve, reject) => {
      obj.getInfo((res, err) => {
        if (err) reject(err);
        else resolve(res);
      });
    });
  }

  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Point([138.7274, 35.3606]).buffer(10000); // Mount Fuji ~10km buffer
  const scale = 1000;
  const maxPixels = 1e9;

  // Cloud masks and NDSI functions
  function maskS2(img) {
    const scl = img.select('SCL');
    const good = scl.neq(3) // cloud shadow
      .and(scl.neq(8)) // cloud medium prob
      .and(scl.neq(9)) // cloud high prob
      .and(scl.neq(10)) // cirrus
      .and(scl.neq(1)) // defective
      .and(scl.neq(2)); // dark area
    return img.updateMask(good);
  }
  function addNDSI_S2(img) {
    const ndsi = img.normalizedDifference(['B3','B11']).rename('NDSI');
    return img.addBands(ndsi);
  }
  function scaleLandsatL2(img) {
    const optical = img.select(['SR_B[1-7]']);
    const scaled = optical.multiply(0.0000275).add(-0.2);
    return img.addBands(scaled, null, true);
  }
  function maskLandsatL2(img) {
    const qa = img.select('QA_PIXEL');
    // Mask clouds, cloud shadow, cirrus, dilated cloud; keep snow
    const mask = qa.bitwiseAnd(1 << 1).eq(0) // dilated cloud
      .and(qa.bitwiseAnd(1 << 2).eq(0)) // cirrus
      .and(qa.bitwiseAnd(1 << 3).eq(0)) // cloud
      .and(qa.bitwiseAnd(1 << 4).eq(0)); // cloud shadow
    return img.updateMask(mask);
  }
  function addNDSI_L8(img) {
    const ndsi = img.normalizedDifference(['SR_B3','SR_B6']).rename('NDSI');
    return img.addBands(ndsi);
  }

  async function computeYear(year) {
    const start = ee.Date.fromYMD(year, 12, 1);
    const end = start.advance(1, 'month');
    let used = 'S2';
    let widened = false;

    // Primary: Sentinel-2 SR
    let s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterDate(start, end)
      .filterBounds(aoi)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 90));
    let s2Count = await getInfoAsync(s2.size());
    if (s2Count === 0) {
      // Fallback: Landsat 8/9 L2
      used = 'L8/9';
      let l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterDate(start, end).filterBounds(aoi);
      let l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterDate(start, end).filterBounds(aoi);
      let lmerge = l8.merge(l9);
      let lCount = await getInfoAsync(lmerge.size());
      if (lCount === 0) {
        // Widen date window ±15 days around December
        widened = true;
        const wStart = start.advance(-15, 'day');
        const wEnd = end.advance(15, 'day');
        s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
          .filterDate(wStart, wEnd)
          .filterBounds(aoi)
          .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 90));
        s2Count = await getInfoAsync(s2.size());
        if (s2Count === 0) {
          used = 'L8/9';
          l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterDate(wStart, wEnd).filterBounds(aoi);
          l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterDate(wStart, wEnd).filterBounds(aoi);
          lmerge = l8.merge(l9);
          lCount = await getInfoAsync(lmerge.size());
          if (lCount === 0) {
            return { year, used: 'None', widened, images: 0, valid: 0, total: 0, validPct: 0, mean: null, cloud: null };
          } else {
            // process Landsat
            const lproc = lmerge.map(scaleLandsatL2).map(maskLandsatL2).map(addNDSI_L8).select('NDSI');
            const comp = lproc.median();
            const valid = await getInfoAsync(comp.reduceRegion({
              reducer: ee.Reducer.count(),
              geometry: aoi,
              scale: scale,
              maxPixels: maxPixels
            }).get('NDSI'));
            const total = await getInfoAsync(ee.Image(1).rename('one').reduceRegion({
              reducer: ee.Reducer.count(),
              geometry: aoi,
              scale: scale,
              maxPixels: maxPixels
            }).get('one'));
            const mean = await getInfoAsync(comp.reduceRegion({
              reducer: ee.Reducer.mean(),
              geometry: aoi,
              scale: scale,
              maxPixels: maxPixels
            }).get('NDSI'));
            const cloud = await getInfoAsync(lmerge.aggregate_mean('CLOUD_COVER'));
            return { year, used: 'L8/9', widened, images: lCount, valid: valid || 0, total: total || 0, validPct: total ? (valid / total * 100) : 0, mean: mean, cloud: cloud };
          }
        }
      } else {
        // process Landsat
        const lproc = lmerge.map(scaleLandsatL2).map(maskLandsatL2).map(addNDSI_L8).select('NDSI');
        const comp = lproc.median();
        const valid = await getInfoAsync(comp.reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: aoi,
          scale: scale,
          maxPixels: maxPixels
        }).get('NDSI'));
        const total = await getInfoAsync(ee.Image(1).rename('one').reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: aoi,
          scale: scale,
          maxPixels: maxPixels
        }).get('one'));
        const mean = await getInfoAsync(comp.reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: aoi,
          scale: scale,
          maxPixels: maxPixels
        }).get('NDSI'));
        const cloud = await getInfoAsync(lmerge.aggregate_mean('CLOUD_COVER'));
        return { year, used: 'L8/9', widened, images: lCount, valid: valid || 0, total: total || 0, validPct: total ? (valid / total * 100) : 0, mean: mean, cloud: cloud };
      }
    }

    // process Sentinel-2
    const s2proc = s2.map(maskS2).map(addNDSI_S2).select('NDSI');
    const comp = s2proc.median();
    const valid = await getInfoAsync(comp.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: aoi,
      scale: scale,
      maxPixels: maxPixels
    }).get('NDSI'));
    const total = await getInfoAsync(ee.Image(1).rename('one').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: aoi,
      scale: scale,
      maxPixels: maxPixels
    }).get('one'));
    const mean = await getInfoAsync(comp.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: aoi,
      scale: scale,
      maxPixels: maxPixels
    }).get('NDSI'));
    const cloud = await getInfoAsync(s2.aggregate_mean('CLOUDY_PIXEL_PERCENTAGE'));
    return { year, used: 'S2', widened, images: s2Count, valid: valid || 0, total: total || 0, validPct: total ? (valid / total * 100) : 0, mean: mean, cloud: cloud };
  }

  try {
    const r2019 = await computeYear(2019);
    const r2020 = await computeYear(2020);

    function fmt(n, digits=3) {
      if (n === null || n === undefined) return 'null';
      return Number(n).toFixed(digits);
    }

    console.log(`Dec2019: Platform=${r2019.used}${r2019.widened ? ' (±15d)' : ''}, Images=${r2019.images}, ValidPix=${r2019.valid}/${r2019.total} (${fmt(r2019.validPct,1)}%), MeanNDSI=${fmt(r2019.mean,3)}, CloudProp=${fmt(r2019.cloud,1)}`);
    console.log(`Dec2020: Platform=${r2020.used${''}}${r2020.widened ? ' (±15d)' : ''}, Images=${r2020.images}, ValidPix=${r2020.valid}/${r2020.total} (${fmt(r2020.validPct,1)}%), MeanNDSI=${fmt(r2020.mean,3)}, CloudProp=${fmt(r2020.cloud,1)}`);

    // Core checks
    if (r2019.images === 0 || r2020.images === 0) {
      console.log('Empty collection for at least one year after recovery attempts.');
      console.log('C1');
      return;
    }
    if (r2019.valid === 0 || r2020.valid === 0) {
      console.log('No valid pixels after masking for at least one year.');
      console.log('C2');
      return;
    }
    const m19 = r2019.mean;
    const m20 = r2020.mean;
    if (m19 === null || m20 === null || !isFinite(m19) || !isFinite(m20) || m19 < -1 || m19 > 1 || m20 < -1 || m20 > 1) {
      console.log('Calculation failure or invalid NDSI range.');
      console.log('C3');
      return;
    }

    // Compare: Was mean NDSI for Dec 2020 lower than Dec 2019?
    const answer = (m20 < m19) ? 'A' : 'B';
    console.log(`DeltaNDSI (2020-2019)=${fmt(m20 - m19,3)}`);
    console.log(answer);
  } catch (e) {
    console.log(`Error: ${e && e.message ? e.message : e}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
